    /// owner allows the local network. `wake` runs on a connection
    /// thread whenever a request is queued. Refused for a read-only
    /// instance and for one whose key is unavailable.
    pub fn listen_remote(
        &mut self,
        wake: impl Fn() + Send + Sync + 'static,
    ) -> io::Result<SocketAddr> {
        self.remote_wake = Some(Arc::new(wake));
        self.bind_remote()
    }

    fn bind_remote(&mut self) -> io::Result<SocketAddr> {
        self.remote = None;
        self.remote_bound = None;
        self.services.advertiser.withdraw();
        if self.core.read_only() {
            return Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                "another instance holds the data directory; not listening",
            ));
        }
        let identity = self
            .core
            .identity()
            .cloned()
            .ok_or_else(|| io::Error::other("no host identity"))?;
        let key = self
            .services
            .secrets
            .get(&identity.key_account())
            .map_err(io::Error::other)?
            .ok_or_else(|| io::Error::other("the remote key is missing"))?;
        let tls = remote::tls_config(&identity, &key).map_err(io::Error::other)?;
        let wake = self
            .remote_wake
            .clone()
            .ok_or_else(|| io::Error::other("no wake"))?;
        let ip = if identity.listen.lan {
            IpAddr::from([0, 0, 0, 0])
        } else {
            IpAddr::from([127, 0, 0, 1])
        };
        let port = self.remote_port_override.unwrap_or(identity.listen.port);
        let waker = Arc::clone(&wake);
        let bound = RemotePort::bind(SocketAddr::new(ip, port), tls, move || waker())?;
        if self.content.is_none() {
            let (tx, rx) = mpsc::channel();
            self.content = Some(ContentWorker::spawn(
                Arc::clone(&self.services.host),
                Arc::clone(&self.services.transcripts),
                Arc::clone(&self.services.secrets),
                tx,
                wake,
            ));
            self.observed = Some(rx);
        }
        let addr = bound.addr();
        self.remote = Some(bound);
        self.remote_bound = Some(identity.listen);
        self.advertise_remote();
        Ok(addr)
    }

    /// Advertise the port over Bonjour while it is bound to the local
    /// network, under the identity's current name; withdrawn otherwise.
    /// A refusal from the responder is logged and leaves the port
    /// reachable by address.
    fn advertise_remote(&mut self) {
        let Some(identity) = self.core.identity() else {
            return;
        };
        let on_lan = self.remote_bound.as_ref().is_some_and(|l| l.lan);
        match self.remote_addr() {
            Some(addr) if on_lan => {
                let ad = Advertisement::new(identity.server_id, &identity.server_name, addr.port());
                if let Err(e) = self.services.advertiser.advertise(&ad) {
                    log::warn!("bonjour: {e}");
                }
            }
            _ => self.services.advertiser.withdraw(),
        }
    }

    /// Where the remote port is bound, while it is.
    #[must_use]
    pub fn remote_addr(&self) -> Option<SocketAddr> {
        self.remote.as_ref().map(RemotePort::addr)
    }

    /// One HTTP request from a device, answered on the frame: `/info`
    /// and `/pair` to anyone, the allowlisted reads to a paired device,
        if field.lost_focus() {
            match draft.port.trim().parse::<u16>() {
                Ok(port) if port != 0 && port != identity.listen.port => {
                    cx.dispatch(AppAction::SetRemoteListen {
                        lan: identity.listen.lan,
                        port,
                    });
                }
                Ok(_) => {}
                Err(_) => draft.port = identity.listen.port.to_string(),
            }
        }
    });
}

/// The pairing window: open it with a scope, or show the code it holds.
fn pairing(cx: &mut DrawCtx<'_>, ui: &mut Ui, draft: &mut RemoteDraft) {
    theme::section(ui, "Pairing");
    let p = theme::palette(ui);
    if cx.core.identity_rotated() {
        ui.label(
            RichText::new(
                "The host's key was remade at this launch, so every earlier pairing is invalid. Pair each device again.",
            )
            .color(p.accent_2_text),
        );
    }
    let Some(identity) = cx.core.identity().cloned() else {
        return;
    };
    if let Some(window) = cx.core.pairing().cloned() {
        let port = cx.remote_port.unwrap_or(identity.listen.port);
        let address = remote::local_address()
            .map(|ip| format!("{ip}:{port}"))
            .unwrap_or_default();
        let payload = serde_json::json!({
            "server_id": identity.server_id,
            "spki_sha256": identity.spki_sha256,
            "code": window.code,
            "addresses": if address.is_empty() { Vec::new() } else { vec![address.clone()] },
        })
        .to_string();
        if draft
            .qr
            .as_ref()
            .is_none_or(|(code, _)| *code != window.code)
        {
            draft.qr = qr_texture(ui.ctx(), &payload).map(|t| (window.code.clone(), t));
        }
        ui.horizontal(|ui| {
            if let Some((_, texture)) = &draft.qr {
                ui.image(egui::load::SizedTexture::from_handle(texture));
            }
            ui.vertical(|ui| {
                ui.label(
                    RichText::new(spaced(&window.code))
                        .text_style(theme::h1())
                        .family(egui::FontFamily::Monospace),
                );
                ui.label(theme::meta_text(
                    ui,
                    format!("Key {}", short_hash(&identity.spki_sha256)),
                ));
                if !address.is_empty() {
                    ui.label(theme::meta_text(ui, format!("Address {address}")));
                }
                ui.label(theme::meta_text(
                    ui,
                    format!(
                        "Scan, or type the key and the code. Grants {} scope. Open for five minutes or three wrong codes.",
                        window.scope.word()
                    ),
                ));
                ui.horizontal(|ui| {
                    // The QR's text, for a client without a camera (the
                    // command-line browser takes it as one argument).
                    if theme::secondary(ui, "Copy invite")
                        .on_hover_text("The QR code's text, to paste into a client")
                        .clicked()
                    {
                        ui.ctx().copy_text(payload.clone());
                    }
                    if theme::secondary(ui, "Stop pairing").clicked() {
                        cx.dispatch(AppAction::ClosePairing);
                    }
                });
            });
        });
    } else {
        ui.horizontal(|ui| {
